// Reference model of the program (lines 1..8; line 9 skipped)
export function run(a,b,c,d,e){
  const A = new Map(); // node -> Map(nbr -> weight)
  const nodeOrder=[];
  function addNode(n){ if(!A.has(n)){ A.set(n,new Map()); nodeOrder.push(n);} }
  function addEdge(u,v,w){ addNode(u); addNode(v); A.get(u).set(v,w); A.get(v).set(u,w); }
  const spec=[[a,b,1.0],[b,c,2.0],[c,d,3.0],[d,e,4.0],[a,e,5.0]];
  for(const [u,v,w] of spec) addEdge(u,v,w);

  // number_of_edges
  let degsum=0, selfloops=0;
  for(const [n,m] of A){ degsum+=m.size; if(m.has(n)) selfloops++; }
  const nEdges=(degsum+selfloops)/2;

  // G[a][b]['weight']
  const wab = A.get(a).get(b);

  // edges() order
  const edges=[]; const seen=new Set();
  for(const n of nodeOrder){ for(const [nbr,w] of A.get(n)){ if(!seen.has(nbr)) edges.push([n,nbr,w]); } seen.add(n); }
  // kruskal (stable sort by weight)
  const parent=new Map(); nodeOrder.forEach(n=>parent.set(n,n));
  const find=x=>{ while(parent.get(x)!==x){ parent.set(x,parent.get(parent.get(x))); x=parent.get(x);} return x; };
  const se=edges.map((t,i)=>[t,i]).sort((p,q)=> p[0][2]-q[0][2] || p[1]-q[1]).map(p=>p[0]);
  const mstEdges=[];
  for(const [u,v,w] of se){ const ru=find(u),rv=find(v); if(ru!==rv){ parent.set(ru,rv); mstEdges.push([u,v]); } }
  const mstCount=mstEdges.length;
  const mstHasAB = mstEdges.some(([u,v])=>(u===a&&v===b)||(u===b&&v===a));

  // dijkstra (networkx _dijkstra_multisource)
  let plen, ppath;
  if(a===e){ plen=['int',0]; ppath=[a]; }
  else {
    const dist=new Map(), seenD=new Map(), paths=new Map([[a,[a]]]);
    let cnt=0; const heap=[];
    const cmp=(x,y)=> x[0]-y[0] || x[1]-y[1];
    const push=(it)=>{heap.push(it); heap.sort(cmp);}; // small n, fine
    const pop=()=>heap.shift();
    seenD.set(a,0); push([0,cnt++,a]);
    while(heap.length){
      const [dv,,v]=pop();
      if(dist.has(v)) continue;
      dist.set(v,dv);
      if(v===e) break;
      for(const [u,cost] of A.get(v)){
        const vu = dist.get(v)+cost;
        if(dist.has(u)){ /* no-op */ }
        else if(!seenD.has(u) || vu < seenD.get(u)){
          seenD.set(u,vu); push([vu,cnt++,u]); paths.set(u, paths.get(v).concat([u]));
        }
      }
    }
    plen=['float',dist.get(e)]; ppath=paths.get(e);
  }

  // bfs_edges (networkx generic_bfs_edges: uses deque of (parent, iter(children)) ... actually bfs_edges uses successors)
  const bfs=[]; { const vis=new Set([a]); let q=[a];
    while(q.length){ const nq=[]; for(const p of q){ for(const ch of A.get(p).keys()){ if(!vis.has(ch)){ vis.add(ch); bfs.push([p,ch]); nq.push(ch);} } } q=nq; } }

  // dfs_edges (stateful iterators)
  const dfs=[]; { const vis=new Set([a]); const stack=[[a, A.get(a).keys()]];
    while(stack.length){ const top=stack[stack.length-1]; const [p,it]=top; let advanced=false;
      let r; while(!(r=it.next()).done){ const ch=r.value; if(!vis.has(ch)){ dfs.push([p,ch]); vis.add(ch); stack.push([ch, A.get(ch).keys()]); advanced=true; break; } }
      if(!advanced) stack.pop(); } }

  const F=x=>Number.isInteger(x)?x.toFixed(1):String(x);
  const L=arr=>'['+arr.join(', ')+']';
  const T=arr=>'['+arr.map(([u,v])=>`(${u}, ${v})`).join(', ')+']';
  return [ String(nEdges), F(wab), String(mstCount), mstHasAB?'True':'False',
           plen[0]==='int'?'0':F(plen[1]), L(ppath), T(bfs), T(dfs) ].join('\n');
}
