import fs from 'fs';
const pats=fs.readFileSync('/workspace/tmp/patterns.txt','utf8').trim().split('\n');
function build(a,b,c,d,e){
  const A=new Map(),ord=[];
  const an=n=>{if(!A.has(n)){A.set(n,new Map());ord.push(n);}};
  for(const [u,v,w] of [[a,b,1],[b,c,2],[c,d,3],[d,e,4],[a,e,5]]){an(u);an(v);A.get(u).set(v,w);A.get(v).set(u,w);}
  return {A,ord};
}
// enumerate ALL simple paths a->e and find all min-weight ones
function allShortest(A,a,e){
  const res=[]; const seen=new Set();
  (function go(n,path,w){ if(n===e && path.length>1){res.push([w,path.slice()]); return;}
    if(path.length>6) return;
    for(const [u,ww] of A.get(n)){ if(path.includes(u)) continue; path.push(u); go(u,path,w+ww); path.pop(); } })(a,[a],0);
  if(a===e) return [];
  const min=Math.min(...res.map(r=>r[0]));
  return res.filter(r=>r[0]===min);
}
// DFS restart-from-scratch variant
function dfsRestart(A,a){
  const out=[],vis=new Set([a]),stack=[a];
  while(stack.length){ const p=stack[stack.length-1]; let found=null;
    for(const ch of A.get(p).keys()) if(!vis.has(ch)){found=ch;break;}
    if(found===null){stack.pop();continue;} out.push([p,found]); vis.add(found); stack.push(found); }
  return out;
}
function dfsStateful(A,a){
  const out=[],vis=new Set([a]),stack=[[a,A.get(a).keys()]];
  while(stack.length){ const [p,it]=stack[stack.length-1]; let adv=false,r;
    while(!(r=it.next()).done){const ch=r.value; if(!vis.has(ch)){out.push([p,ch]);vis.add(ch);stack.push([ch,A.get(ch).keys()]);adv=true;break;}}
    if(!adv) stack.pop(); }
  return out;
}
const T=x=>'['+x.map(([u,v])=>`(${u}, ${v})`).join(', ')+']';
let ties=[], dfsDiff=[];
for(const p of pats){
  const [a,b,c,d,e]=p.split(' ').map(Number);
  const {A,ord}=build(a,b,c,d,e);
  const obs=fs.readFileSync(`/workspace/tmp/out/${p.replace(/ /g,'_')}.txt`,'utf8').split('\n');
  const sp=allShortest(A,a,e);
  const uniq=[...new Set(sp.map(r=>JSON.stringify(r[1])))];
  if(uniq.length>1) ties.push({p, min:sp[0][0], cands:uniq, chosen:obs[6], adjA:[...A.get(a).keys()]});
  if(T(dfsRestart(A,a))!==T(dfsStateful(A,a))) dfsDiff.push(p);
}
console.log('=== DIJKSTRA TIE CASES (multiple distinct min-weight simple paths) ===');
for(const t of ties) console.log(`${t.p}  minW=${t.min}  candidates=${t.cands.join(' | ')}  CHOSEN=${t.chosen}  adj[a]=[${t.adjA}]`);
console.log('\n=== DFS stateful vs restart differ on: ===', dfsDiff.length?dfsDiff:'(none of 52)');
// adjacency dump for a few
for(const p of ['1 2 1 3 2','1 2 3 2 4','1 2 3 1 4','1 1 2 2 3','1 2 3 4 5','1 2 2 3 3']){
  const [a,b,c,d,e]=p.split(' ').map(Number); const {A,ord}=build(a,b,c,d,e);
  console.log(`\nadj for ${p}: nodeOrder=[${ord}]`);
  for(const [n,m] of A) console.log(`  ${n}: `+[...m].map(([k,v])=>`${k}(w=${v})`).join(', '));
}
